public class RecursiveFactorial {
    static long factorial(int n) {
        if (n < 0 || n > 20) {
            throw new IllegalArgumentException("n must be from 0 to 20");
        }
        if (n == 0) {
            return 1;
        }
        return n * factorial(n - 1);
    }

    static long factorialWithTrace(int n, StringBuilder trace) {
        if (n < 0 || n > 20) {
            throw new IllegalArgumentException("n must be from 0 to 20");
        }
        trace.append("call ").append(n).append('\n');
        if (n == 0) {
            trace.append("return 1\n");
            return 1;
        }
        long result = n * factorialWithTrace(n - 1, trace);
        trace.append("return ").append(result).append('\n');
        return result;
    }

    static void expect(Class<? extends Throwable> type, Runnable action) {
        try {
            action.run();
        } catch (Throwable error) {
            if (type.isInstance(error)) return;
            throw error;
        }
        throw new AssertionError("expected " + type.getSimpleName());
    }

    public static void main(String[] args) {
        assert factorial(0) == 1;
        assert factorial(1) == 1;
        assert factorial(5) == 120;
        assert factorial(20) == 2432902008176640000L;
        expect(IllegalArgumentException.class, () -> factorial(-1));
        expect(IllegalArgumentException.class, () -> factorial(21));

        StringBuilder trace = new StringBuilder();
        assert factorialWithTrace(4, trace) == 24;
        String expected = "call 4\ncall 3\ncall 2\ncall 1\ncall 0\n"
                + "return 1\nreturn 1\nreturn 2\nreturn 6\nreturn 24\n";
        assert trace.toString().equals(expected) : trace;
        System.out.println("recursive-factorial checks: OK");
    }
}

